 "<div style=\"font-family:'Montserrat', sans-serif;font-size:56px;font-weight:800;color:#ffb347;line-height:1\">218<span style=\"font-size:24px;color:#a9bdd3\"> m</span></div><div style=\"margin-top:6px\">de largo</div>": "<div style=\"font-family:'Montserrat', sans-serif;font-size:56px;font-weight:800;color:#ffb347;line-height:1\">218<span style=\"font-size:24px;color:#a9bdd3\"> m</span></div><div style=\"margin-top:6px\">de comprimento</div>",
